//B"H

/**
 * B"H — Blender-like automation node editor view helpers.
 *
 * This module owns graph markup only: toolbar, node cards, connection fields,
 * start selector, and JSON mirror. The panel controller wires actions, storage,
 * archive, and relay behavior separately.
 */
export function renderGraphFields(graph = {}) {
  return `<section class="automation-graph-panel">
    <h2>Automation Graph</h2>
    <p class="panel-note">Build rules like: if the last AI message contains text or regex, route to another node, archive, delay, jump, send, or stop. JSON is still the source of truth.</p>
    <div class="graph-toolbar">
      <button type="button" data-graph-action="add-send">+ Send</button>
      <button type="button" data-graph-action="add-condition">+ Condition</button>
      <button type="button" data-graph-action="add-archive">+ Archive</button>
      <button type="button" data-graph-action="add-delay">+ Delay</button>
      <button type="button" data-graph-action="add-jump">+ Jump</button>
      <button type="button" data-graph-action="add-stop">+ Stop</button>
      <button type="button" data-graph-action="reset">Reset</button>
      <button type="button" data-graph-action="save-forms">Save Forms</button>
      <button type="button" data-graph-action="save-json">Save JSON</button>
      <button type="button" data-graph-action="download-json">Download JSON</button>
    </div>
    <label class="automation-field graph-start-field">Start node <select data-graph-start>${nodeOptions(graph.nodes || [], graph.start)}</select></label>
    <div class="graph-canvas">${(graph.nodes || []).map((node, index) => nodeEditor(node, index, graph.nodes || [])).join("")}</div>
    <label class="automation-field graph-json-field">Graph JSON<textarea data-graph-json rows="14">${text(JSON.stringify(graph, null, 2))}</textarea></label>
    <div class="automation-status" id="graph-status">graph ready: ${(graph.nodes || []).length} node(s)</div>
  </section>`;
}

export function captureGraphFormsFromRoot(root, graph = {}) {
  const start = root.querySelector("[data-graph-start]")?.value || graph.start;
  const nodes = [...root.querySelectorAll("[data-graph-node]")].map(card => {
    const node = {};
    card.querySelectorAll("[data-node-field]").forEach(input => {
      node[input.dataset.nodeField] = input.type === "checkbox" ? input.checked : input.value;
    });
    return node;
  });
  return { version: 1, start, nodes };
}

export function createGraphNode(type, index) {
  const id = `${type}-${index + 1}`;
  return {
    id,
    type,
    label: `${type} ${index + 1}`,
    match: "",
    negate: false,
    regex: false,
    flags: "i",
    delayMs: type === "delay" ? 1000 : 0,
    maxTurns: 0,
    archiveQuery: "",
    prompt: type === "send" ? "continue with the next precise verified step" : "",
    archiveTag: type === "archive" || type === "send" ? "graph" : "",
    onTrue: "",
    onFalse: "",
    next: ""
  };
}

function nodeEditor(node, index, list = []) {
  return `<article class="graph-node graph-node-${attr(node.type)}" data-graph-node>
    <div class="graph-node-head"><strong>${text(node.label || node.id)}</strong><span>${text(node.type)}</span><button type="button" data-graph-action="delete:${attr(node.id)}">×</button></div>
    <div class="graph-node-grid">
      ${nodeInput("id", "ID", node.id)}
      ${nodeSelect("type", "Type", node.type, ["condition", "send", "archive", "delay", "jump", "stop"])}
      ${nodeInput("label", "Label", node.label)}
      ${nodeInput("archiveTag", "Archive tag", node.archiveTag)}
      ${nodeInput("match", node.regex ? "Regex" : "Contains text", node.match)}
      ${nodeCheckbox("regex", "Use regex", node.regex)}
      ${nodeInput("flags", "Regex flags", node.flags || "i")}
      ${nodeInput("delayMs", "Delay ms", node.delayMs || 0)}
      ${nodeInput("maxTurns", "Max turns at node", node.maxTurns || 0)}
      ${nodeInput("archiveQuery", "Archive query/ref", node.archiveQuery || "")}
      ${nodeCheckbox("negate", "Negate condition", node.negate)}
      ${nodeSelect("onTrue", "On true", node.onTrue, ["", ...list.map(n => n.id)])}
      ${nodeSelect("onFalse", "On false", node.onFalse, ["", ...list.map(n => n.id)])}
      ${nodeSelect("next", "Next", node.next, ["", ...list.map(n => n.id)])}
    </div>
    <label class="automation-field graph-node-prompt">Prompt<textarea data-node-field="prompt" rows="4">${text(node.prompt || "")}</textarea></label>
    <p>${text(describeNode(node))}</p>
  </article>`;
}

function describeNode(node) {
  if (node.type === "condition") return `${node.negate ? "unless" : "if"} last message ${node.regex ? "matches" : "contains"} "${node.match}" → ${node.onTrue || "?"} / ${node.onFalse || "?"}`;
  if (node.type === "send") return `send: ${node.prompt || "settings prompt"}`;
  if (node.type === "archive") return `archive as ${node.archiveTag || node.id} then ${node.next || "stop"}`;
  if (node.type === "delay") return `wait ${node.delayMs || 0}ms then ${node.next || "stop"}`;
  if (node.type === "jump") return `jump to ${node.next || "stop"}`;
  return "stop";
}

function nodeInput(name, labelText, value = "") { return `<label class="automation-field">${labelText}<input data-node-field="${name}" value="${attr(value)}"></label>`; }
function nodeCheckbox(name, labelText, value = false) { return `<label class="automation-field graph-toggle"><input data-node-field="${name}" type="checkbox" ${value ? "checked" : ""}> ${labelText}</label>`; }
function nodeSelect(name, labelText, value, values) { return `<label class="automation-field">${labelText}<select data-node-field="${name}">${values.map(item => `<option value="${attr(item)}" ${item === value ? "selected" : ""}>${text(item || "—")}</option>`).join("")}</select></label>`; }
function nodeOptions(nodes = [], selected = "") { return nodes.map(node => `<option value="${attr(node.id)}" ${node.id === selected ? "selected" : ""}>${text(node.label || node.id)}</option>`).join(""); }
function attr(value) { return String(value ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
function text(value) { return String(value ?? "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
